import os
import secrets
from fastapi import FastAPI, HTTPException, Depends
from fastapi.responses import RedirectResponse
from pydantic import BaseModel
from sqlite3 import connect
from typing import Optional

app = FastAPI()

db_path = os.getenv('DB_PATH', 'shortener.db')

class URLRequest(BaseModel):
    url: str

def validate_url(url: str) -> bool:
    if not url.startswith(('http://', 'https://')):
        return False
    if 'javascript:' in url or '://' in url.split('://')[1]:
        return False
    if any(ip in url for ip in ('localhost', '127.0', '169.254', '192.168', '10')):
        return False
    return True

@app.post('/links')
async def create_link(request: URLRequest):
    url = request.url
    if not validate_url(url):
        raise HTTPException(status_code=422, detail='Invalid URL')

    conn = connect(db_path)
    cursor = conn.cursor()

    for _ in range(5):
        code = secrets.token_urlsafe(8)[:8]
        cursor.execute('SELECT * FROM Link WHERE short_code = ?', (code,))
        if not cursor.fetchone():
            cursor.execute('INSERT INTO Link (short_code, original_url) VALUES (?, ?)', (code, url))
            conn.commit()
            return {'short_code': code}

    raise HTTPException(status_code=503, detail='Five code-collision attempts exhausted')

@app.get('/r/{code}')
async def redirect(code: str):
    conn = connect(db_path)
    cursor = conn.cursor()

    cursor.execute('SELECT original_url FROM Link WHERE short_code = ?', (code,))
    result = cursor.fetchone()

    if not result:
        raise HTTPException(status_code=404, detail='Code not found')

    cursor.execute('UPDATE Link SET click_count = click_count + 1 WHERE short_code = ?', (code,))
    conn.commit()

    return RedirectResponse(result[0], status_code=307)

@app.get('/links/{code}')
async def get_stats(code: str):
    conn = connect(db_path)
    cursor = conn.cursor()

    cursor.execute('SELECT original_url, click_count FROM Link WHERE short_code = ?', (code,))
    result = cursor.fetchone()

    if not result:
        raise HTTPException(status_code=404, detail='Code not found')

    return {
        'original_url': result[0],
        'click_count': result[1]
    }

if __name__ == '__main__':
    import uvicorn
    uvicorn.run(app, host='0.0.0.0', port=8000)

